import { readFile } from 'node:fs/promises';
import sharp from 'sharp';
import { expect, it } from 'vitest';

// Generated by scripts/assets.mjs (npm test runs it first) and copied to dist by scripts/build.mjs.
async function glyph(file: string) {
  const { data, info } = await sharp(file).raw().toBuffer({ resolveWithObject: true });
  let top = info.height,
    bottom = -1,
    colored = 0;
  for (let y = 0; y < info.height; y++)
    for (let x = 0; x < info.width; x++) {
      const i = (y * info.width + x) * 4;
      if (data[i + 3] === 0) continue;
      top = Math.min(top, y);
      bottom = Math.max(bottom, y);
      if (data[i] || data[i + 1] || data[i + 2]) colored++;
    }
  return { width: info.width, height: info.height, glyphHeight: bottom - top + 1, colored };
}

it('sizes the menu bar icon like other menu bar icons, at 1x and 2x', async () => {
  // 16 pt, not the full 22 pt menu bar height; a 2x file so Retina never upscales a bitmap.
  expect(await glyph('resources/trayTemplate.png')).toEqual({
    width: 16,
    height: 16,
    glyphHeight: 16,
    colored: 0,
  });
  expect(await glyph('resources/trayTemplate@2x.png')).toEqual({
    width: 32,
    height: 32,
    glyphHeight: 32,
    colored: 0,
  });
});

it('ships the 2x image next to the 1x template the tray loads', async () => {
  const build = await readFile('scripts/build.mjs', 'utf8');
  expect(build).toContain("'dist/trayTemplate@2x.png'");
  const tray = await readFile('src/main/tray.ts', 'utf8');
  expect(tray).toContain("'trayTemplate.png'");
  expect(tray).toContain('setTemplateImage(true)');
});
